+      sed: _SlotModule(rec),
+      awk: _SlotModule(rec),
+      tar: _SlotModule(rec),
+      gzip: _SlotModule(rec),
+      zip: _SlotModule(rec),
+      python: _SlotModule(rec),
+      qjs: _SlotModule(rec),
+      sqlite3: _SlotModule(rec),
+      lua: _SlotModule(rec),
+      sandboxHostPath: sandbox.path,
